  margin-bottom: 0.75rem;
}

.single-post-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 1.6rem + 2vw, 3.25rem);
  line-height: 1.15;
  color: var(--color-navy-deep);
  margin-bottom: var(--space-md);
}

.single-post-body {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-text-primary);
}

.single-post-body p {
  margin-bottom: var(--space-md);
}

.single-post-body h2,
.single-post-body h3 {
  margin-top: var(--space-xl);
